#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    static int count;
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {
        count = count + 1;
    }

    static int howMany() {
        return count;
    }

    void show() const {
        cout << name << " 有 " << fish << " 条" << endl;
    }
};

